def svc_head(eyebrow,h,p=''):return f'<div class="svc-head"><div><div class="eyebrow">{eyebrow}</div><h2>{h}</h2></div>'+(f'<p>{p}</p>' if p else '')+'</div>'
def svc_facts(items):return '<div class="svc-facts">'+''.join(f'<div><span>{E(k)}</span><p>{v}</p></div>' for k,v in items)+'</div>'
def svc_tiles(items,cls='svc-tiles'):
 return f'<div class="{cls}">'+''.join(f'<article><span class="svc-num">{i+1:02d}</span><h3>{h}</h3><p>{p}</p>'+(('<ul>'+''.join(f'<li>{x}</li>' for x in li)+'</ul>') if li else '')+'</article>' for i,(h,p,*rest) in enumerate(items) for li in [rest[0] if rest else None])+'</div>'
def svc_timeline(items):
 return f'<ol class="svc-timeline" style="--n:{len(items)}">'+''.join(f'<li><span class="svc-num">{i+1:02d} / {E(label.upper())}</span><h3>{h}</h3><p>{p}</p><p class="svc-out"><b>You get</b>{out}</p></li>' for i,(label,h,p,out) in enumerate(items))+'</ol>'
def svc_checks(items):return '<ul class="svc-checks">'+''.join(f'<li>{x}</li>' for x in items)+'</ul>'
def svc_faq(items,title='Questions we are often asked.'):
 ld=json.dumps({'@context':'https://schema.org','@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in items]},ensure_ascii=False).replace('</','<\\/')
 return '<section class="section svc-faq-section">'+svc_head('FAQS',title,'Something else on your mind? <a href="/contact-us/">Ask us directly ↗</a>')+'<div class="svc-faq">'+''.join(f'<details><summary>{E(q)}<b aria-hidden="true">＋</b></summary><p>{E(a)}</p></details>' for q,a in items)+f'</div><script type="application/ld+json">{ld}</script></section>'
