 return '<section class="section tone-paper">'+svc_head('RELATED SERVICES','Connected at every stage.','Each service stands on its own, and each is stronger with the others alongside it.')+cards([('services/'+s['slug'],s['title'],s['summary'],s['tag']) for s in others]+[('how-we-work','How we work','See how the brief, the design and the build stay connected from first meeting to move-in.','THE APPROACH')])+'</section>'
